import ipaddress
import json
import sys

TARGET = "192.168.1.0"
SCOPE = ipaddress.ip_network("192.168.1.0/24")


def main():
    address = ipaddress.ip_address(TARGET)
    if address not in SCOPE:
        print(json.dumps({"status": "error", "error": "Target is outside the supplied scope", "target": TARGET, "scope": str(SCOPE)}))
        return 2

    try:
        from framework_evidence import run_tool
    except Exception as exc:
        print(json.dumps({"status": "error", "error": "Could not load framework_evidence helper", "detail": str(exc)}))
        return 2

    argv = ["nmap", "-sV", "-p-", TARGET]
    try:
        result = run_tool(argv)
    except Exception as exc:
        print(json.dumps({"status": "error", "command": argv, "error": "Tool invocation failed", "detail": str(exc)}))
        return 1

    if isinstance(result, str):
        print(result)
    else:
        try:
            print(json.dumps(result, ensure_ascii=False, default=str))
        except Exception as exc:
            print(json.dumps({"status": "error", "command": argv, "error": "Could not serialize tool envelope", "detail": str(exc)}))
            return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

