import json
import re
import sys

import framework_evidence

SEARCH_TERMS = ["type:exploit ssh", "type:auxiliary ssh", "openssh"]
MODULE_RE = re.compile(r"\b(?:exploit|auxiliary|post|encoder|payload|evasion)/[A-Za-z0-9_./-]+")


def envelope_stdout(value):
    """Collect stdout strings from common evidence-envelope shapes."""
    found = []
    if isinstance(value, dict):
        text = value.get("stdout")
        if isinstance(text, str):
            found.append(text)
        runs = value.get("tool_runs")
        if isinstance(runs, list):
            for run in runs:
                found.extend(envelope_stdout(run))
        structured = value.get("structured_output")
        if isinstance(structured, dict):
            found.extend(envelope_stdout(structured))
    elif isinstance(value, list):
        for item in value:
            found.extend(envelope_stdout(item))
    return found


def main():
    result = {
        "purpose": "Installed Metasploit catalog search and candidate metadata review only; no module is loaded or executed against the remote service.",
        "search_terms": SEARCH_TERMS,
        "search_envelope": None,
        "candidate_paths_observed": [],
        "metadata_envelope": None,
        "coverage_notes": [],
        "errors": [],
    }

    search_command = "search type:exploit ssh; search type:auxiliary ssh; search openssh; exit -y"
    try:
        search_envelope = framework_evidence.run_tool(
            ["msfconsole", "-q", "-x", search_command]
        )
        result["search_envelope"] = search_envelope
        search_text = "\n".join(envelope_stdout(search_envelope))
        matches = set()
        for match in MODULE_RE.findall(search_text):
            path = match.rstrip(".,:;)]}")
            lower = path.lower()
            if "/ssh/" in lower or "openssh" in lower:
                matches.add(path)
        candidates = sorted(matches)
        result["candidate_paths_observed"] = candidates
        result["coverage_notes"].append(
            "Search output was examined for module paths containing an SSH path segment or OpenSSH in the module name; raw output and structured fields remain in search_envelope."
        )
        if not search_text:
            result["coverage_notes"].append(
                "No stdout text was available to parse; candidate discovery is inconclusive, not a no-match finding."
            )
        elif not candidates:
            result["coverage_notes"].append(
                "No plausible SSH/OpenSSH module path was identified in the captured search stdout. This applies only to the captured output and its coverage."
            )

        if candidates:
            info_commands = "; ".join("info " + path for path in candidates)
            info_commands += "; exit -y"
            try:
                result["metadata_envelope"] = framework_evidence.run_tool(
                    ["msfconsole", "-q", "-x", info_commands]
                )
            except Exception as exc:
                result["errors"].append(
                    "Metadata query failed: " + type(exc).__name__ + ": " + str(exc)
                )
        else:
            result["coverage_notes"].append(
                "Metadata review was not attempted because no candidate path was recoverable from captured search output."
            )
    except Exception as exc:
        result["errors"].append(
            "Catalog search failed: " + type(exc).__name__ + ": " + str(exc)
        )
        result["coverage_notes"].append(
            "The catalog search did not produce adequate evidence; this is not a finding that no applicable module exists."
        )

    json.dump(result, sys.stdout, ensure_ascii=False, sort_keys=True)
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()

