import json
import re

import framework_evidence

QUERIES = [
    ("OpenSSH-named exploits", "search name:openssh type:exploit"),
    ("CVE-2024-6387 exploits", "search cve:2024-6387 type:exploit"),
]
UNAVAILABLE_MODULE = "exploit/linux/ssh/openssh_race_condition"
MODULE_RE = re.compile(r"\b(?:exploit|auxiliary)/[A-Za-z0-9_./-]+")


def run_console(command):
    return framework_evidence.run_tool(
        ["msfconsole", "-q", "-x", command + "; exit -y"]
    )


def stream_text(envelope, key):
    if isinstance(envelope, dict):
        value = envelope.get(key, "")
        return value if isinstance(value, str) else ""
    return ""


search_runs = []
candidates = []
seen = set()
for label, query in QUERIES:
    envelope = run_console(query)
    raw_text = stream_text(envelope, "stdout") + "\n" + stream_text(envelope, "stderr")
    found = []
    for match in MODULE_RE.finditer(raw_text):
        module = match.group(0).rstrip(".,:;)")
        if module == UNAVAILABLE_MODULE or module in found:
            continue
        found.append(module)
        if module not in seen:
            seen.add(module)
            candidates.append(module)
    search_runs.append({
        "label": label,
        "query": query,
        "tool_envelope": envelope,
        "module_paths_extracted_from_raw_streams": found,
    })

metadata_runs = []
for module in candidates:
    metadata_runs.append({
        "module": module,
        "request": "info " + module,
        "tool_envelope": run_console("info " + module),
    })

print(json.dumps({
    "purpose": "Focused installed Metasploit catalog discovery and metadata review only; no module was loaded or executed.",
    "query_coverage": [
        "search name:openssh type:exploit",
        "search cve:2024-6387 type:exploit",
    ],
    "search_runs": search_runs,
    "metadata_candidates": candidates,
    "metadata_runs": metadata_runs,
