import glob
import json
import os
import shutil


def check_directory(path):
    result = {"path": path, "exists": False, "accessible": False}
    try:
        result["exists"] = os.path.isdir(path)
        if result["exists"]:
            result["accessible"] = os.access(path, os.R_OK | os.X_OK)
            if result["accessible"]:
                try:
                    result["entry_count"] = sum(1 for _ in os.scandir(path))
                except OSError as exc:
                    result["listing_error"] = str(exc)
    except OSError as exc:
        result["check_error"] = str(exc)
    return result


def main():
    executable = shutil.which("msfconsole")
    executable_realpath = os.path.realpath(executable) if executable else None
    candidates = {
        "/usr/share/metasploit-framework/modules",
        "/usr/local/share/metasploit-framework/modules",
        "/usr/lib/metasploit-framework/modules",
        "/opt/metasploit-framework/modules",
        "/opt/metasploit-framework/embedded/framework/modules",
    }
    if executable_realpath:
        executable_dir = os.path.dirname(executable_realpath)
        candidates.update({
            os.path.join(executable_dir, "modules"),
            os.path.normpath(os.path.join(executable_dir, "..", "share", "metasploit-framework", "modules")),
            os.path.normpath(os.path.join(executable_dir, "..", "..", "share", "metasploit-framework", "modules")),
        })
    candidates.update(glob.glob("/usr/lib/ruby/gems/*/gems/metasploit-framework-*/modules"))
    candidates.update(glob.glob("/var/lib/gems/*/gems/metasploit-framework-*/modules"))

    metadata = {"attempted": False, "command": ["dpkg-query", "-L", "metasploit-framework"]}
    try:
        import framework_evidence
        metadata["attempted"] = True
        envelope = framework_evidence.run_tool(metadata["command"])
        metadata["tool_envelope"] = envelope
        # Use package file-list paths only to add focused candidate directories.
        runs = envelope.get("tool_runs", []) if isinstance(envelope, dict) else []
        for run in runs:
            stdout = run.get("stdout", "") if isinstance(run, dict) else ""
            for line in stdout.splitlines():
                path = line.strip()
                if path.endswith("/modules") and "metasploit" in path.lower():
                    candidates.add(path)
    except Exception as exc:
        metadata["error"] = str(exc)

    checks = [check_directory(path) for path in sorted(candidates)]
    found = [item["path"] for item in checks if item["exists"] and item["accessible"]]
    print(json.dumps({
        "purpose": "Locate an installed, accessible Metasploit module tree using local executable, filesystem, and package-file-list evidence only.",
        "msfconsole": {"path": executable, "resolved_path": executable_realpath, "found_on_path": executable is not None},
        "module_tree_checks": checks,
        "accessible_module_trees": found,
        "located": bool(found),
        "package_metadata": metadata,
        "coverage": {
            "checks_performed": ["PATH lookup for msfconsole", "focused standard installation paths", "module directories adjacent to the resolved executable", "Ruby gem module-directory patterns", "dpkg-query package file list for metasploit-framework when available"],
            "not_performed": ["Metasploit console searches", "module loading", "remote service assessment", "unbounded filesystem scan"],
            "interpretation": "If no accessible directory is listed, the tree was not located by these checks; that does not establish that no relevant modules exist."
        }
    }, sort_keys=True))


if __name__ == "__main__":
    main()

