#!/usr/bin/env python3
"""Read-only inspection of installed Metasploit SSH/OpenSSH module source."""
import json
import os
from pathlib import Path

ROOT = Path('/usr/share/metasploit-framework/modules')
KEYWORDS = (
    'unauth', 'without authentication', 'no authentication', 'login_required',
    'auth_required', 'authentication', 'credential', 'username', 'password',
    'checkcode', 'targets', 'disclosuredate', 'references', 'privileged',
    'sessiontype', 'register_options', 'rport', 'rhosts', 'openssh',
    'ssh_version', 'ssh_banner', 'required_cmd', 'platform',
)

def main():
    result = {
        'purpose': 'Static, read-only inspection of installed Metasploit module source; no module is loaded or executed and no remote request is made.',
        'tree': str(ROOT),
        'tree_exists': ROOT.is_dir(),
        'coverage': {
            'method': 'Recursively enumerate .rb files beneath the located modules tree; inspect source text for files whose relative path has an ssh component or whose source mentions OpenSSH.',
            'ruby_files_enumerated': 0,
            'ssh_path_files': 0,
            'openssh_source_matches_outside_ssh_path': 0,
            'read_errors': [],
        },
        'candidates': [],
    }
    if not ROOT.is_dir():
        result['coverage']['error'] = 'Located module tree is not accessible as a directory at execution time.'
        print(json.dumps(result, indent=2, sort_keys=True))
        return

    for current, dirs, files in os.walk(ROOT, onerror=lambda e: result['coverage']['read_errors'].append(str(e))):
        dirs.sort()
        for name in sorted(files):
            if not name.endswith('.rb'):
                continue
            path = Path(current) / name
            result['coverage']['ruby_files_enumerated'] += 1
            rel = path.relative_to(ROOT).as_posix()
            path_is_ssh = any(part.lower() == 'ssh' for part in Path(rel).parts[:-1]) or 'ssh' in name.lower()
            try:
                source = path.read_text(encoding='utf-8', errors='replace')
            except OSError as exc:
                result['coverage']['read_errors'].append({'path': rel, 'error': str(exc)})
                continue
            open_ssh = 'openssh' in source.lower()
            if path_is_ssh:
                result['coverage']['ssh_path_files'] += 1
            if open_ssh and not path_is_ssh:
                result['coverage']['openssh_source_matches_outside_ssh_path'] += 1
            if not (path_is_ssh or open_ssh):
                continue

            lines = source.splitlines()
            # Metasploit module declarations conventionally occur near the start;
            # retain a bounded source excerpt rather than attempting to interpret Ruby.
            head = '\n'.join(lines[:100])[:6500]
            selected = []
            for index, line in enumerate(lines):
                low = line.lower()
                if any(word in low for word in KEYWORDS):
                    start, end = max(0, index - 1), min(len(lines), index + 2)
                    for n in range(start, end):
                        item = {'line': n + 1, 'text': lines[n][:500]}
                        if item not in selected:
                            selected.append(item)
            # Preserve source-order and keep metadata indicators interpretable.
            selected.sort(key=lambda item: item['line'])
            result['candidates'].append({
                'path': rel,
                'module_category': Path(rel).parts[0] if Path(rel).parts else '',
                'path_has_ssh_component_or_name': path_is_ssh,
                'source_mentions_openssh': open_ssh,
                'static_source_excerpt_first_100_lines': head,
                'prerequisite_and_access_related_source_lines': selected[:100],
                'interpretation_limit': 'Static text only. Ruby declarations are not evaluated; keyword absence does not prove a prerequisite or access requirement is absent.',
            })

    result['coverage']['candidate_source_files_inspected'] = len(result['candidates'])
    result['coverage']['inspection_complete'] = not result['coverage']['read_errors']
    print(json.dumps(result, indent=2, sort_keys=True))

if __name__ == '__main__':
    main()

