#!/usr/bin/env python3
import json
import os
import re

ROOT = "/usr/share/metasploit-framework/modules"
SSH_RE = re.compile(r"\b(?:ssh|openssh)\b", re.IGNORECASE)
ACCESS_RE = re.compile(
    r"unauthenticated|without authentication|authentication bypass|auth(?:entication)?\s+bypass|no authentication|pre-auth|preauth",
    re.IGNORECASE,
)
META_RE = re.compile(
    r"\b(?:Name|Description|DisclosureDate|Author|References|Platform|Arch|Targets|DefaultTarget|Notes|Privileged|SessionTypes|Stability|Reliability|SideEffects)\b|"
    r"register_options|Opt(?:String|Int|Bool|Port|Address|Enum)|USERNAME|PASSWORD|RHOSTS|RPORT|def check|def exploit",
    re.IGNORECASE,
)

def main():
    result = {
        "purpose": "Read-only static review of installed module source metadata; no module is loaded or executed and no remote request is made.",
        "tree": ROOT,
        "tree_exists": os.path.isdir(ROOT),
        "coverage": {
            "ruby_files_enumerated": 0,
            "ssh_related_files": 0,
            "candidate_files_reviewed": 0,
            "read_errors": [],
            "candidate_rule": "SSH/OpenSSH-related Ruby source in modules/exploits, or SSH/OpenSSH-related source explicitly mentioning unauthenticated access or authentication bypass.",
            "limitations": "Static text matching and selected source lines are not a complete Ruby semantic analysis. A catalog/source match does not establish applicability to the observed service, remote vulnerability, or student access."
        },
        "candidates": []
    }
    if not result["tree_exists"]:
        result["coverage"]["read_errors"].append({"path": ROOT, "error": "module tree is not accessible as a directory"})
        print(json.dumps(result, sort_keys=True))
        return

    for base, dirs, files in os.walk(ROOT, followlinks=False):
        dirs.sort()
        for filename in sorted(files):
            if not filename.endswith(".rb"):
                continue
            path = os.path.join(base, filename)
            result["coverage"]["ruby_files_enumerated"] += 1
            try:
                with open(path, "r", encoding="utf-8", errors="replace") as handle:
                    lines = handle.readlines()
            except OSError as exc:
                result["coverage"]["read_errors"].append({"path": os.path.relpath(path, ROOT), "error": str(exc)})
                continue

            text = "".join(lines)
            path_rel = os.path.relpath(path, ROOT)
            is_ssh_related = bool(SSH_RE.search(path_rel) or SSH_RE.search(text))
            if not is_ssh_related:
                continue
            result["coverage"]["ssh_related_files"] += 1
            in_exploit_tree = path_rel.startswith("exploits" + os.sep)
            has_auth_bypass_text = bool(ACCESS_RE.search(text))
            if not (in_exploit_tree or has_auth_bypass_text):
                continue

            selected = []
            for number, line in enumerate(lines, 1):
                if META_RE.search(line):
                    clean = line.strip()
                    if len(clean) > 300:
                        clean = clean[:297] + "..."
                    selected.append({"line": number, "text": clean})
            result["candidates"].append({
                "path": path_rel,
                "classification_basis": [
                    label for label, matched in (
                        ("source is under modules/exploits", in_exploit_tree),
                        ("source mentions unauthenticated access or authentication bypass", has_auth_bypass_text),
                    ) if matched
                ],
                "ssh_related": True,
                "selected_metadata_and_prerequisite_lines": selected,
            })

    result["coverage"]["candidate_files_reviewed"] = len(result["candidates"])
    print(json.dumps(result, sort_keys=True))

if __name__ == "__main__":
    main()

