import json
import os
import re

TREE = "/usr/share/metasploit-framework/modules"


def shorten(text, limit=240):
    text = " ".join(text.strip().split())
    return text if len(text) <= limit else text[:limit - 3] + "..."


def emit(value):
    print(json.dumps(value, ensure_ascii=False, sort_keys=True))


if not os.path.isdir(TREE) or not os.access(TREE, os.R_OK | os.X_OK):
    emit({
        "tree": TREE,
        "tree_readable": False,
        "error": "Located module tree is not readable at execution time.",
        "modules_scanned": 0,
        "candidate_files": [],
    })
    raise SystemExit(0)

ruby_files = []
read_errors = []
walk_errors = []

def onerror(error):
    walk_errors.append({"path": getattr(error, "filename", None), "error": str(error)})

for root, dirs, files in os.walk(TREE, onerror=onerror):
    dirs.sort()
    for name in sorted(files):
        if name.endswith(".rb"):
            ruby_files.append(os.path.join(root, name))

candidates = []
ssh_context = re.compile(r"\bssh\b|openssh", re.IGNORECASE)
security_context = re.compile(
    r"unauth|pre.?auth|without authentication|no authentication|auth(?:entication)?\s*(?:bypass|vuln)|"
    r"login|credential|remote code|command execution|CVE-20|exploit",
    re.IGNORECASE,
)
metadata_pattern = re.compile(
    r"['\"](?:Name|Description|References|DisclosureDate|Rank|Notes|Privileged|Platform|Arch)['\"]\s*=>|"
    r"\b(?:register_options|register_advanced_options|Opt::RHOSTS|Opt::RPORT|OptString\.new|"
    r"OptBool\.new|OptPort\.new|AutoCheck|def check|def exploit)\b|"
    r"\b(?:USERNAME|PASSWORD|USER_FILE|PASS_FILE|PRIVATE_KEY|KEY_FILE)\b",
    re.IGNORECASE,
)

for path in ruby_files:
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as source_file:
            text = source_file.read()
    except OSError as exc:
        read_errors.append({"path": os.path.relpath(path, TREE), "error": str(exc)})
        continue

    rel = os.path.relpath(path, TREE).replace(os.sep, "/")
    path_is_ssh = bool(re.search(r"(?:^|/)ssh(?:/|_|\.)", rel, re.IGNORECASE))
    has_openssh = bool(re.search(r"openssh", text, re.IGNORECASE))
    if not path_is_ssh and not (has_openssh and security_context.search(text)):
        continue

    lines = text.splitlines()
    metadata = []
    prerequisites = []
    for number, line in enumerate(lines, 1):
        if metadata_pattern.search(line):
            item = {"line": number, "text": shorten(line)}
            if re.search(
                r"Name|Description|References|DisclosureDate|Rank|Notes|Privileged|Platform|Arch",
                line,
                re.IGNORECASE,
            ):
                if len(metadata) < 8:
                    metadata.append(item)
            else:
                if len(prerequisites) < 12:
                    prerequisites.append(item)

    # Keep the evidence as source excerpts; do not infer that a source declaration
    # proves applicability to the observed host.
    candidates.append({
        "module_path": rel,
        "selection_basis": "SSH in module path" if path_is_ssh else "OpenSSH source mention plus security context",
        "metadata_source_lines": metadata,
        "option_or_execution_declaration_lines": prerequisites,
        "metadata_excerpt_coverage": "up to 8 matching source lines; excerpts are not parsed Ruby metadata",
        "prerequisite_excerpt_coverage": "up to 12 matching source lines; declarations may be conditional",
    })

emit({
    "purpose": "Read-only static source review; no module loading, module execution, or remote requests.",
    "tree": TREE,
    "tree_readable": True,
    "coverage": {
        "ruby_files_discovered": len(ruby_files),
        "candidate_files_reported": len(candidates),
        "read_errors": read_errors,
        "directory_walk_errors": walk_errors,
        "selection": "All readable Ruby files whose relative path contains an SSH module path segment/name, plus files mentioning OpenSSH alongside security-context terms.",
        "limitations": "Static keyword and source-line review only. Excerpts are not a complete Ruby parse; conditional logic and requirements may require manual review. Unreported files, unreadable files, and output truncation must not be treated as negative findings.",
    },
    "candidates": candidates,
})

