#!/usr/bin/env python3
"""Read-only static review of SSH/OpenSSH-related Metasploit module sources."""
import json
import os
import re

ROOT = "/usr/share/metasploit-framework/modules"
AREAS = {"exploit", "auxiliary", "post"}
SSH_RE = re.compile(r"\b(?:ssh|openssh)\b", re.IGNORECASE)
META_RE = re.compile(
    r"\b(?:Name|Description|References|Targets|DefaultTarget|Rank|Platform|Arch|DisclosureDate|Privileged)\b|"
    r"'?(?:Name|Description|References|Targets|DefaultTarget|Rank|Platform|Arch|DisclosureDate|Privileged)'?\s*=>",
    re.IGNORECASE,
)
ACCESS_RE = re.compile(
    r"\b(?:auth(?:entication|orized)?|credential|username|password|login|session|"
    r"check|version|target|openssh|ssh|key|private_key|publickey|anonymous|unauthenticated)\b",
    re.IGNORECASE,
)


def excerpt(line, limit=220):
    text = " ".join(line.strip().split())
    return text if len(text) <= limit else text[: limit - 3] + "..."


def main():
    if not os.path.isdir(ROOT):
        print(json.dumps({
            "tree": ROOT, "tree_readable": False, "error": "module tree is not a readable directory",
            "purpose": "Read-only static source review; no module loading, execution, or remote requests."
        }, sort_keys=True))
        return

    discovered = 0
    area_ruby = {area: 0 for area in sorted(AREAS)}
    signal_count = 0
    candidates = []
    read_errors = []
    walk_errors = []

    def on_walk_error(exc):
        walk_errors.append({"path": getattr(exc, "filename", None), "error": str(exc)})

    for base, dirs, files in os.walk(ROOT, onerror=on_walk_error):
        dirs.sort()
        for filename in sorted(files):
            if not filename.endswith(".rb"):
                continue
            full = os.path.join(base, filename)
            rel = os.path.relpath(full, ROOT).replace(os.sep, "/")
            discovered += 1
            parts = rel.split("/")
            if parts[0] not in AREAS:
                continue
            area_ruby[parts[0]] += 1
            try:
                with open(full, "r", encoding="utf-8", errors="replace") as stream:
                    lines = stream.readlines()
            except OSError as exc:
                read_errors.append({"path": rel, "error": str(exc)})
                continue

            path_signal = any("ssh" in part.lower() for part in parts)
            hit_lines = [(i + 1, line) for i, line in enumerate(lines) if SSH_RE.search(line)]
            source_signal = bool(hit_lines)
            if not path_signal and not source_signal:
                continue
            signal_count += 1

            # Keep every SSH/OpenSSH signal in the three module areas, including
            # scanners and post modules whose source may state an authentication
            # or existing-session prerequisite that rules them out for unauthenticated access.
            metadata = [
                {"line": n, "text": excerpt(line)}
                for n, line in enumerate(lines, 1) if META_RE.search(line)
            ][:4]
            access = [
                {"line": n, "text": excerpt(line)}
                for n, line in hit_lines if ACCESS_RE.search(line)
            ][:6]
            candidates.append({
                "path": rel,
                "area": parts[0],
                "selection_signals": [
                    label for label, present in (("SSH/OpenSSH in path", path_signal),
                                                 ("SSH/OpenSSH in source", source_signal)) if present
                ],
                "metadata_source_lines": metadata,
                "ssh_and_prerequisite_source_lines": access,
                "source_line_count": len(lines),
            })

    candidates.sort(key=lambda item: item["path"])
    result = {
        "purpose": "Read-only static source review; no module loading, execution, or remote requests.",
        "tree": ROOT,
        "tree_readable": True,
        "coverage": {
            "ruby_files_discovered_in_tree": discovered,
            "ruby_files_by_reviewed_area": area_ruby,
            "reviewed_areas": sorted(AREAS),
            "files_selected_by_path_or_source_ssh_openssh_signal": signal_count,
            "candidate_files_reported": len(candidates),
        },
        "selection_basis": "Read every Ruby file under exploit/, auxiliary/, and post/; report files whose relative path contains an SSH component/name or whose source contains the SSH/OpenSSH token. This is an inclusive review set, not proof that every match provides unauthenticated access or applies to OpenSSH 9.2p1 Debian.",
        "target_context": "Observed service: OpenSSH 9.2p1 Debian at 192.168.1.0:22. Compare only with source-stated applicability and prerequisites; no remote service assessment was performed.",
        "candidates": candidates,
        "read_errors": read_errors,
        "walk_errors": walk_errors,
        "limitations": "Excerpts are static Ruby source evidence, not parsed or executed module behavior. Review full source for conditional behavior when excerpts are insufficient. A source match, module metadata, or version reference does not establish remote vulnerability or access.",
    }
    print(json.dumps(result, sort_keys=True, ensure_ascii=False))


if __name__ == "__main__":
    main()

