#!/usr/bin/env python3
"""Read-only, heuristic source review of SSH-signal Metasploit exploit files."""
import json
import os
import re

ROOT = "/usr/share/metasploit-framework/modules/exploits"
SSH_RE = re.compile(r"\b(?:open)?ssh\b", re.I)
META_RE = re.compile(r"['\"](?:Name|Description)['\"]\s*=>|\b(?:Name|Description)\s*=", re.I)
PREREQ_RE = re.compile(
    r"USERNAME|PASSWORD|PASS_FILE|USER_FILE|PRIVATE_KEY|KEY_PATH|\bauth(?:enticate|entication)?\b|"
    r"\blogin\b|\bcredentials?\b|\b(?:root|user)\s+password\b|\bprior access\b|\bsession\b",
    re.I,
)
ROLE_RE = re.compile(r"\b(?:client|server|daemon|sshd|connect|listen|SRVPORT|RHOSTS)\b", re.I)


def compact(text, limit=210):
    text = " ".join(text.strip().split())
    return text if len(text) <= limit else text[: limit - 3] + "..."


def walk_files():
    errors = []
    found = []
    for base, dirs, files in os.walk(ROOT):
        dirs.sort()
        for name in sorted(files):
            if name.endswith(".rb"):
                found.append(os.path.join(base, name))
    return found, errors


def main():
    if not os.path.isdir(ROOT):
        print(json.dumps({"purpose": "Read-only SSH exploit source review", "tree": ROOT,
                          "tree_readable": False, "limitation": "Exploit tree directory is unavailable."}, indent=2))
        return

    files, walk_errors = walk_files()
    signals, read_errors = [], []
    for path in files:
        try:
            with open(path, "r", encoding="utf-8", errors="replace") as f:
                lines = f.readlines()
        except OSError as exc:
            read_errors.append({"path": os.path.relpath(path, ROOT), "error": str(exc)})
            continue
        rel = os.path.relpath(path, ROOT).replace(os.sep, "/")
        matched = [i for i, line in enumerate(lines) if SSH_RE.search(line)]
        if matched:
            signals.append((rel, lines, matched))

    # A candidate must be an SSH-named/path exploit or declare SSH/OpenSSH in
    # its Name/Description metadata; other textual hits are retained separately.
    candidates, other = [], []
    for rel, lines, matched in signals:
        path_signal = bool(re.search(r"(?:^|/)ssh(?:/|_|\.)|_ssh", rel, re.I))
        meta_indices = [i for i, line in enumerate(lines) if META_RE.search(line)]
        metadata_signal = any(SSH_RE.search(lines[i]) for i in meta_indices)
        candidate = path_signal or metadata_signal
        item = {"path": rel, "lines": lines, "matched": matched, "candidate": candidate}
        (candidates if candidate else other).append(item)

    reviewed = []
    for item in candidates:
        lines = item["lines"]
        meta_indices = [i for i, line in enumerate(lines) if META_RE.search(line)]
        # Include concise Name/Description lines, plus nearby continuation text.
        applicability = []
        for i in meta_indices:
            if len(applicability) >= 4:
                break
            low = lines[i].lower()
            if "name" in low or "description" in low or SSH_RE.search(lines[i]):
                applicability.append({"line": i + 1, "text": compact(lines[i])})
                if i + 1 < len(lines) and ("description" in low or "name" in low) and len(applicability) < 4:
                    nxt = lines[i + 1]
                    if nxt.strip() and not META_RE.search(nxt):
                        applicability.append({"line": i + 2, "text": compact(nxt)})
        if not applicability:
            applicability = [{"line": i + 1, "text": compact(lines[i])}
                             for i in item["matched"][:2]]

        prereq = []
        for i, line in enumerate(lines):
            if PREREQ_RE.search(line):
                prereq.append({"line": i + 1, "text": compact(line)})
                if len(prereq) >= 4:
                    break
        role = []
        for i, line in enumerate(lines):
            if ROLE_RE.search(line) and ("ssh" in line.lower() or "client" in line.lower()
                                          or "server" in line.lower() or "listen" in line.lower()):
                role.append({"line": i + 1, "text": compact(line)})
                if len(role) >= 2:
                    break
        reviewed.append({
            "path": item["path"],
            "role_or_scope_source_cues": role,
            "applicability_source_cues": applicability[:4],
            "credential_or_access_prerequisite_source_cues": prereq,
            "interpretation_limit": (
                "These are source excerpts, not full control-flow analysis. No matching prerequisite cue in the excerpts "
                "does not prove unauthenticated access; client-side modules require a vulnerable client role."
            ),
        })

    other_files = []
    for item in other:
        lines = item["lines"]
        other_files.append({
            "path": item["path"],
            "ssh_signal_lines": [i + 1 for i in item["matched"][:5]],
            "excerpt": compact(lines[item["matched"][0]]) if item["matched"] else "",
            "triage": "SSH text signal, but neither SSH-named/path nor SSH/OpenSSH Name/Description metadata matched the candidate rule",
        })

    report = {
        "purpose": "Read-only static source review; no module loading, execution, or remote requests.",
        "tree": ROOT,
        "tree_readable": True,
        "ruby_files_discovered": len(files),
        "ssh_signal_files_read": len(signals),
        "candidate_rule": "SSH in module path/name or SSH/OpenSSH in Name/Description metadata; heuristic, not a vulnerability determination.",
        "plausible_candidates_reviewed": len(reviewed),
        "reported_prior_candidate_count": 36,
        "candidate_count_matches_prior_report": len(reviewed) == 36,
        "candidate_reviews": reviewed,
        "other_ssh_signal_files": other_files,
        "other_ssh_signal_file_count": len(other_files),
        "walk_errors": walk_errors,
        "read_errors": read_errors,
        "limitations": "Static excerpts identify documented scope and visible prerequisite cues only. They do not prove remote service applicability, vulnerability, exploitability, or access. Candidates with sparse or indirect source cues need manual full-source review.",
    }
    print(json.dumps(report, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

