#!/usr/bin/env python3
"""Read-only, source-level review of SSH-signal Metasploit exploit files."""
import json
import os
import re
from pathlib import Path

TREE = Path('/usr/share/metasploit-framework/modules/exploits')
SSH_RE = re.compile(r'\b(?:open)?ssh\b', re.I)
NAME_RE = re.compile(r"['\"]Name['\"]\s*=>\s*['\"]([^'\"]+)['\"]")
TEXT_RE = re.compile(r"['\"](?:Description|Notes|DefaultOptions)['\"]\s*=>\s*['\"](.*)", re.I)
AUTH_RE = re.compile(r'username|password|credential|authentication|authenticate|login|auth_methods|net::ssh\.start', re.I)
CLIENT_RE = re.compile(r'vulnerable client|ssh client|client connects|client connection|srvport|tcpserver|accept\(', re.I)
SESSION_RE = re.compile(r'\b(?:session|meterpreter|post module|local exploit|requires? (?:an? )?session)\b', re.I)
UNAUTH_RE = re.compile(r'unauthenticated|without authentication|no authentication required|prior to authentication', re.I)


def short(text, limit=190):
    text = re.sub(r'\s+', ' ', text.strip())
    return text if len(text) <= limit else text[:limit - 1].rstrip() + '…'


def read_source(path):
    try:
        return path.read_text(encoding='utf-8', errors='replace').splitlines(), None
    except OSError as exc:
        return None, f'{type(exc).__name__}: {exc}'


def inspect(path, lines):
    rel = path.relative_to(TREE).as_posix()
    source = '\n'.join(lines)
    name = next((m.group(1) for line in lines if (m := NAME_RE.search(line))), '')
    # Candidate designation requires an SSH-specific path or module name, or
    # an SSH-specific description paired with exploit/service context.
    head = '\n'.join(lines[:100])
    ssh_name = bool(SSH_RE.search(name))
    ssh_path = bool(re.search(r'(^|/)ssh(/|_)|ssh', rel, re.I))
    ssh_description = bool(SSH_RE.search(head[:12000]))
    exploit_context = bool(re.search(r'exploit|vulnerab|overflow|authentication|default password|command execution', head, re.I))
    candidate = ssh_path or ssh_name or (ssh_description and exploit_context)

    auth_lines = [(i, line) for i, line in enumerate(lines, 1) if AUTH_RE.search(line)]
    client_lines = [(i, line) for i, line in enumerate(lines, 1) if CLIENT_RE.search(line)]
    session_lines = [(i, line) for i, line in enumerate(lines, 1) if SESSION_RE.search(line)]
    unauth_lines = [(i, line) for i, line in enumerate(lines, 1) if UNAUTH_RE.search(line)]

    prereqs = []
    if unauth_lines:
        prereqs.append('source explicitly describes an unauthenticated/pre-authentication condition')
    if auth_lines:
        prereqs.append('authentication/credential-related source present; inspect evidence to determine whether it is required')
    if client_lines and (re.search(r'client', rel + ' ' + name, re.I) or re.search(r'srvport|tcpserver|accept\(', source, re.I)):
        prereqs.append('client-side/listener indicators; appears to target an SSH client or require a connecting client')
    if session_lines and re.search(r'Msf::Post|session|local exploit|post module', head, re.I):
        prereqs.append('session/local/post-access indicators; may require prior access')
    if not prereqs:
        prereqs.append('no explicit access prerequisite classified by these cues; unauthenticated access is not established')

    evidence = []
    # Include module identity and descriptive source lines, then source lines
    # bearing on access/role. Each excerpt is bounded to keep the report concise.
    for i, line in enumerate(lines, 1):
        if NAME_RE.search(line) or re.search(r"['\"]Description['\"]\s*=>|This module|This exploit|vulnerability occurs|default credentials", line, re.I):
            evidence.append({'line': i, 'text': short(line, 150)})
            if len(evidence) >= 3:
                break
    for group in (unauth_lines, auth_lines, client_lines, session_lines):
        if len(evidence) >= 6:
            break
        for i, line in group:
            if not any(e['line'] == i for e in evidence):
                evidence.append({'line': i, 'text': short(line, 150)})
                break
    return {
        'path': rel,
        'name': name or None,
        'classification': 'plausible_direct_candidate' if candidate else 'other_ssh_signal',
        'source_indicated_prerequisites': prereqs if candidate else None,
        'evidence': evidence,
    }


def main():
    report = {
        'purpose': 'Read-only static source review; no module loading, execution, or remote requests.',
        'tree': str(TREE),
        'tree_readable': TREE.is_dir(),
        'reported_prior_counts': {'ssh_signal_files': 62, 'plausible_direct_candidates': 36},
        'ssh_signal_files': 0,
        'plausible_direct_candidates': 0,
        'candidate_records': [],
        'other_ssh_signal_files': [],
        'walk_errors': [],
        'read_errors': [],
        'limitations': 'Candidate designation and signal discovery use lexical/source metadata cues. The excerpts are not complete control-flow analysis; credential-related text may not be a required prerequisite, and absence of such text does not establish unauthenticated access. Static source cannot establish applicability to or vulnerability of a remote service.',
    }
    if not TREE.is_dir():
        report['walk_errors'].append(f'exploit tree is not readable or not a directory: {TREE}')
        print(json.dumps(report, separators=(',', ':')))
        return

    paths = []
    for root, dirs, files in os.walk(TREE, onerror=lambda exc: report['walk_errors'].append(str(exc))):
        dirs.sort()
        for filename in sorted(files):
            if filename.endswith('.rb'):
                paths.append(Path(root) / filename)
    for path in paths:
        lines, error = read_source(path)
        if error:
            report['read_errors'].append({'path': str(path.relative_to(TREE)), 'error': error})
            continue
        source = '\n'.join(lines)
        if not SSH_RE.search(path.as_posix()) and not SSH_RE.search(source):
            continue
        record = inspect(path, lines)
        report['ssh_signal_files'] += 1
        if record['classification'] == 'plausible_direct_candidate':
            report['plausible_direct_candidates'] += 1
            report['candidate_records'].append(record)
        else:
            report['other_ssh_signal_files'].append({
                'path': record['path'],
                'name': record['name'],
                'evidence': record['evidence'][:2],
            })
    report['coverage_comparison'] = {
        'ssh_signal_count_matches_prior_report': report['ssh_signal_files'] == 62,
