#!/usr/bin/env python3
"""Read-only static review of SSH/OpenSSH-signal Metasploit auxiliary Ruby files."""
import json
import os
import re

ROOT = "/usr/share/metasploit-framework/modules/auxiliary"
SSH_SIGNAL = re.compile(
    r"(?:\bssh\b|openssh|net::ssh|ssh[_:/.-]|secure shell|secure-shell)", re.I
)
UNAUTH = re.compile(r"unauthenticated|without authentication|no authentication|anonymous", re.I)
ACCESS = re.compile(r"login|authenticat|credential|password|private.?key|command|execute|shell|session|access", re.I)
CRED_OPTION = re.compile(
    r"(?:Opt\w*\.new|Opt\w*\()\s*['\"](?:USERNAME|USER|PASSWORD|PASS_FILE|PRIVATE_KEY|KEY_FILE|SSH_KEY|PUBKEY|KEY_PATH)['\"]",
    re.I,
)
OPTION = re.compile(r"\b(?:OptString|OptBool|OptInt|OptPort|OptPath|OptEnum|OptAddress)\b|Opt::RPORT", re.I)


def clean_line(text, limit=190):
    text = " ".join(text.strip().split())
    return text if len(text) <= limit else text[: limit - 3] + "..."


def is_ssh_path(relpath):
    return any(re.search(r"ssh|openssh", part, re.I) for part in relpath.split(os.sep))


def review_file(relpath, lines):
    source = "\n".join(lines)
    name_lines = []
    description_lines = []
    option_lines = []
    access_lines = []

    for number, raw in enumerate(lines, 1):
        s = raw.strip()
        low = s.lower()
        if re.search(r"['\"]Name['\"]\s*=>|\bName\s*=", s):
            name_lines.append((number, clean_line(s)))
        if re.search(r"['\"]Description['\"]\s*=>|\bDescription\s*=", s):
            description_lines.append((number, clean_line(s)))
        if OPTION.search(s) and (CRED_OPTION.search(s) or re.search(r"\[\s*true\s*,", s, re.I)):
            option_lines.append((number, clean_line(s)))
        if ACCESS.search(s) and ("#" in s or "description" in low or "unauth" in low or "credential" in low):
            access_lines.append((number, clean_line(s)))

    explicit_unauth = bool(UNAUTH.search(source))
    credential_options = bool(CRED_OPTION.search(source))
    login_or_exec = bool(re.search(r"login|authenticat|session|shell|exec_command|execute|command", source, re.I))
    scanner = bool(re.search(r"scanner|probe|fingerprint|enumerat|version|audit|check", relpath + "\n" + source, re.I))

    if explicit_unauth and login_or_exec and not credential_options:
        bucket = "explicit_unauthenticated_access_candidate"
    elif credential_options and login_or_exec:
        bucket = "credentialed_or_key-dependent_access_functionality"
    elif scanner:
        bucket = "scanner_or_non_access_functionality"
    else:
        bucket = "other_ssh_auxiliary_functionality"

    # Keep a compact, auditable evidence set: metadata, credential options, then
    # source lines that describe authentication or the module's SSH behavior.
    evidence = []
    for group in (name_lines, description_lines, option_lines, access_lines):
        for number, text in group:
            item = {"line": number, "text": text}
            if item not in evidence:
                evidence.append(item)
            if len(evidence) >= 5:
                break
        if len(evidence) >= 5:
            break

    # If the first selected lines were generic metadata, retain an SSH-related
    # source line as an additional pointer where the compact limit permits.
    if len(evidence) < 5:
        for number, raw in enumerate(lines, 1):
            if SSH_SIGNAL.search(raw):
                item = {"line": number, "text": clean_line(raw)}
                if item not in evidence:
                    evidence.append(item)
                if len(evidence) >= 5:
                    break

    return {
        "path": relpath.replace(os.sep, "/"),
        "review_bucket": bucket,
        "explicit_unauthenticated_language": explicit_unauth,
        "credential_option_seen": credential_options,
        "source_evidence": evidence,
        "assessment_limit": "Bucket is a static-source heuristic; verify the cited source and full control flow before drawing applicability conclusions.",
    }


def main():
    report = {
        "purpose": "Read-only static source review; no module loading, execution, or remote requests.",
        "tree": ROOT,
        "tree_readable": os.path.isdir(ROOT) and os.access(ROOT, os.R_OK),
        "ruby_files_discovered": 0,
        "ssh_signal_files": 0,
        "read_errors": [],
        "walk_errors": [],
        "review_buckets": {},
        "files": [],
        "applicability_note": "The observed service is OpenSSH 9.2p1 Debian at 192.168.1.0:22. Source metadata may document functionality and prerequisites, but does not establish that the service is vulnerable or that a module applies to that version/platform.",
    }
    if not report["tree_readable"]:
        report["limitation"] = "The located auxiliary tree is absent or unreadable in this execution environment."
        print(json.dumps(report, sort_keys=True))
        return

    def onerror(exc):
        report["walk_errors"].append({"path": getattr(exc, "filename", None), "error": str(exc)})

    for base, dirs, names in os.walk(ROOT, onerror=onerror):
        dirs.sort()
        for filename in sorted(names):
            if not filename.endswith(".rb"):
                continue
            report["ruby_files_discovered"] += 1
            path = os.path.join(base, filename)
            relpath = os.path.relpath(path, ROOT)
            try:
                with open(path, "r", encoding="utf-8", errors="replace") as handle:
                    lines = handle.read().splitlines()
            except OSError as exc:
                report["read_errors"].append({"path": relpath, "error": str(exc)})
                continue
            if not is_ssh_path(relpath) and not SSH_SIGNAL.search("\n".join(lines)):
                continue
            entry = review_file(relpath, lines)
            report["files"].append(entry)
            report["review_buckets"][entry["review_bucket"]] = report["review_buckets"].get(entry["review_bucket"], 0) + 1

    report["ssh_signal_files"] = len(report["files"])
    report["files"].sort(key=lambda item: item["path"].lower())
    if report["read_errors"] or report["walk_errors"]:
        report["coverage_status"] = "incomplete_or_errors_present"
    else:
        report["coverage_status"] = "all_discovered_auxiliary_ruby_files_read"
    print(json.dumps(report, ensure_ascii=False, sort_keys=True))


if __name__ == "__main__":
    main()

