import json
import os
import re

TREE = "/usr/share/metasploit-framework/modules/auxiliary"
SSH_PATH = re.compile(r"(?:^|[/_-])(?:ssh|openssh)(?:$|[/_-])", re.I)
SSH_TEXT = re.compile(r"\b(?:ssh|openssh)\b|libssh", re.I)
ACCESS_TEXT = re.compile(r"unauthenticated|without authentication|no authentication|anonymous|login|authenticate|credential|private.?key|public.?key|session|shell|execute|command execution|remote execution|access", re.I)
EXPLICIT_UNAUTH = re.compile(r"unauthenticated|without authentication|no authentication|anonymous", re.I)
CREDENTIAL = re.compile(r"Opt(?:String|Path|Bool|Enum|Int|Address)\.new\s*\(\s*['\"](?:USERNAME|USER|PASSWORD|PASS|PRIVATE_KEY|KEY_FILE|KEY_PATH|SSH_KEY|PRIVATEKEY|KEYPASS|KEY_PASSWORD)['\"]|USERNAME|PASSWORD|PRIVATE_KEY|KEY_FILE|KEY_PATH|SSH_KEY|KEYPASS", re.I)
SCANNER = re.compile(r"scanner|\bscan(?:ner|ning)?\b|version detection|enumerat(?:e|ion)", re.I)
ACCESS_ACTION = re.compile(r"login|authenticate|session|shell|execute|command|exploit|payload|add.*key|authorized_keys", re.I)
RELEVANT = re.compile(r"'Name'|'Description'|Opt(?:String|Path|Bool|Enum|Int|Address)\.new|unauthenticated|without authentication|no authentication|anonymous|credential|username|password|private.?key|public.?key|login|authenticate|session|shell|execute|command|scanner|scan|version|enumerat|ssh|openssh", re.I)


def read_text(path):
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        return f.read()


def classify(rel, text):
    lines = text.splitlines()
    access = bool(ACCESS_TEXT.search(text) and ACCESS_ACTION.search(text))
    explicit = bool(EXPLICIT_UNAUTH.search(text) and ACCESS_ACTION.search(text))
    credentialed = bool(CREDENTIAL.search(text))
    scanner_only = bool(SCANNER.search(rel) or SCANNER.search(text)) and not access
    if explicit:
        return "explicit_unauthenticated_access_candidate"
    if access and credentialed:
        return "credentialed_or_key_dependent_access_functionality"
    if access:
        return "other_ssh_auxiliary_functionality"
    return "scanner_or_non_access_functionality"


def evidence_lines(text, limit=7):
    out = []
    for number, line in enumerate(text.splitlines(), 1):
        if RELEVANT.search(line):
            excerpt = line.strip()
            if len(excerpt) > 240:
                excerpt = excerpt[:237] + "..."
            out.append({"line": number, "text": excerpt})
            if len(out) >= limit:
                break
    return out


def main():
    if not os.path.isdir(TREE):
        print(json.dumps({"tree": TREE, "tree_readable": False, "limitation": "The located auxiliary module tree is not present or readable at the expected path."}, sort_keys=True))
        return

    ruby_files = []
    walk_errors = []
    read_errors = []
    for root, dirs, files in os.walk(TREE, onerror=lambda e: walk_errors.append(str(e))):
        dirs.sort()
        for name in sorted(files):
            if name.endswith(".rb"):
                ruby_files.append(os.path.join(root, name))

    signals = []
    for path in ruby_files:
        try:
            text = read_text(path)
        except OSError as exc:
            read_errors.append({"path": os.path.relpath(path, TREE), "error": str(exc)})
            continue
        rel = os.path.relpath(path, TREE).replace(os.sep, "/")
        if SSH_PATH.search("/" + rel + "/") or SSH_TEXT.search(text):
            signals.append((rel, text, classify(rel, text)))

    counts = {}
    for _, _, category in signals:
        counts[category] = counts.get(category, 0) + 1

    # Include source evidence for each plausible access-related file; scanners and
    # non-access modules are accounted for by exact paths and category counts.
    candidates = []
    for rel, text, category in signals:
        if category == "scanner_or_non_access_functionality":
            continue
        candidates.append({
            "path": rel,
            "classification": category,
            "source_evidence": evidence_lines(text),
            "applicability_note": "Static source clues only; check the complete source and its conditions before concluding applicability. The observed OpenSSH 9.2p1 Debian service was not assessed.",
        })

    scanners_nonaccess = [rel for rel, _, category in signals if category == "scanner_or_non_access_functionality"]
    result = {
        "purpose": "Read-only static source review; no module loading, execution, or remote requests.",
        "tree": TREE,
        "tree_readable": True,
        "ruby_files_discovered": len(ruby_files),
        "ssh_signal_files": len(signals),
        "classification_counts": counts,
        "scanner_or_non_access_file_paths": scanners_nonaccess,
        "plausible_access_related_candidates": candidates,
        "coverage_method": "Walked every Ruby file under the auxiliary tree; marked SSH signals from SSH/OpenSSH path components or SSH/OpenSSH/libssh source references. Categories are heuristic labels, not proof of behavior or target applicability.",
        "limitations": "Displayed source excerpts are not a Ruby parse and may omit conditional behavior or prerequisites. Review full source for any candidate before concluding its exact applicability. A version banner alone does not establish vulnerability.",
        "walk_errors": walk_errors,
        "read_errors": read_errors,
    }
    print(json.dumps(result, sort_keys=True))


if __name__ == "__main__":
    main()

