#!/usr/bin/env python3
"""Read-only source review of SSH/OpenSSH signal files in Metasploit payload/post trees."""
import json
import re
from pathlib import Path

ROOT = Path("/usr/share/metasploit-framework/modules")
TREES = ("payloads", "post")
SIGNAL = re.compile(r"ssh|openssh", re.IGNORECASE)
RELEVANT = re.compile(
    r"ssh|openssh|session|meterpreter|shell|auth|credential|login|user|password|"
    r"exploit|vulnerab|platform|arch|payload|description|name|rank|privilege|"
    r"required|option|connect|command|execute|include|type|target",
    re.IGNORECASE,
)


def main():
    report = {"purpose": "Read-only static source review; no module loading, execution, or remote requests.",
              "root": str(ROOT), "trees": [], "limitations": "SSH/OpenSSH signal is a source/path heuristic. Printed excerpts are source evidence, not proof of remote applicability or vulnerability."}
    for tree_name in TREES:
        tree = ROOT / tree_name
        result = {"tree": str(tree), "tree_readable": tree.is_dir(), "ruby_files": 0,
                  "ssh_signal_files": 0, "files": [], "read_errors": []}
        if tree.is_dir():
            try:
                paths = sorted(p for p in tree.rglob("*.rb") if p.is_file())
            except OSError as exc:
                paths = []
                result["read_errors"].append({"path": str(tree), "error": str(exc)})
            result["ruby_files"] = len(paths)
            for path in paths:
                try:
                    text = path.read_text(encoding="utf-8", errors="replace")
                except OSError as exc:
                    result["read_errors"].append({"path": str(path), "error": str(exc)})
                    continue
                if not SIGNAL.search(str(path)) and not SIGNAL.search(text):
                    continue
                result["ssh_signal_files"] += 1
                lines = text.splitlines()
                selected = []
                for number, line in enumerate(lines, 1):
                    stripped = line.strip()
                    if stripped and RELEVANT.search(stripped):
                        # Keep output concise while retaining source line references.
                        if len(stripped) > 220:
                            stripped = stripped[:217] + "..."
                        selected.append({"line": number, "text": stripped})
                result["files"].append({"path": str(path.relative_to(ROOT)),
                                        "source_line_count": len(lines),
                                        "relevant_source_lines": selected})
        else:
            result["read_errors"].append({"path": str(tree), "error": "module tree is not a readable directory"})
        report["trees"].append(result)
    print(json.dumps(report, ensure_ascii=False, separators=(",", ":")))


if __name__ == "__main__":
    main()

