import json
import os
import shutil
from pathlib import Path


def add_candidate(path, candidates):
    try:
        path = Path(path).expanduser()
        # An environment-provided value may name either the modules directory
        # itself or the framework installation root.
        for candidate in (path, path / "modules"):
            try:
                if candidate.is_dir() and candidate.name == "modules":
                    resolved = candidate.resolve()
                    candidates[str(resolved)] = resolved
            except OSError:
                pass
    except (OSError, TypeError, ValueError):
        pass


def main():
    candidates = {}
    attempted = []
    discovery_methods = []

    env_root = os.environ.get("METASPLOIT_FRAMEWORK_ROOT")
    if env_root:
        discovery_methods.append("METASPLOIT_FRAMEWORK_ROOT environment variable")
        add_candidate(Path(env_root), candidates)

    executable = shutil.which("msfconsole")
    if executable:
        discovery_methods.append("msfconsole executable lookup and resolved-path ancestors")
        try:
            exe_path = Path(executable).resolve()
            for ancestor in (exe_path.parent, *exe_path.parents):
                add_candidate(ancestor / "modules", candidates)
        except OSError as exc:
            attempted.append({"path": executable, "error": str(exc)})
    else:
        discovery_methods.append("msfconsole executable lookup (not found on PATH)")

    standard_locations = [
        "/usr/share/metasploit-framework/modules",
        "/usr/local/share/metasploit-framework/modules",
        "/opt/metasploit-framework/embedded/framework/modules",
        "/opt/metasploit-framework/modules",
        "/usr/lib/metasploit-framework/modules",
    ]
    discovery_methods.append("check common Metasploit installation locations")
    for value in standard_locations:
        p = Path(value)
        attempted.append({"path": value, "exists": p.is_dir()})
        add_candidate(p, candidates)

    results = []
    for root in sorted(candidates.values(), key=str):
        examined_entries = 0
        examined_source_files = 0
        examined_directories = 0
        matches = []
        errors = []
        skipped_symlink_dirs = []

        def onerror(exc):
            errors.append({"path": getattr(exc, "filename", None), "error": str(exc)})

        for current, dirnames, filenames in os.walk(root, topdown=True, followlinks=False, onerror=onerror):
            examined_directories += 1
            current_path = Path(current)
            kept_dirs = []
            for dirname in sorted(dirnames):
                child = current_path / dirname
                try:
                    if child.is_symlink():
                        skipped_symlink_dirs.append(str(child))
                    else:
                        kept_dirs.append(dirname)
                except OSError as exc:
                    errors.append({"path": str(child), "error": str(exc)})
            dirnames[:] = kept_dirs

            for filename in filenames:
                path = current_path / filename
                examined_entries += 1
                try:
                    if path.is_file() and path.suffix.lower() == ".rb":
                        examined_source_files += 1
                        relative = path.relative_to(root).as_posix()
                        components = relative.casefold().split("/")
                        if any("ssh" in component or "openssh" in component for component in components):
                            matches.append(str(path))
                except OSError as exc:
                    errors.append({"path": str(path), "error": str(exc)})

        results.append({
            "module_root": str(root),
            "inventory_method": "recursive os.walk of the module tree; Ruby (.rb) source files matched by SSH/OpenSSH terms in path components; no source contents read",
            "ssh_openssh_source_paths": sorted(matches),
            "matching_path_count": len(matches),
            "filesystem_file_entries_examined": examined_entries,
            "ruby_source_files_examined": examined_source_files,
            "directories_examined": examined_directories,
            "traversal_errors": errors,
            "symlink_directories_not_followed": skipped_symlink_dirs,
            "coverage_complete_for_non_symlink_tree": not errors,
            "coverage_limitations": (["One or more filesystem traversal or inspection errors occurred."] if errors else []) + (["Symlink directories were not followed."] if skipped_symlink_dirs else [])
        })

    output = {
        "purpose": "Locate and inventory installed Metasploit SSH/OpenSSH module source paths only; no module loading, execution, or remote requests.",
        "comparison_target_supplied_by_task": "OpenSSH 9.2p1 Debian",
        "discovery_methods": discovery_methods,
        "attempted_standard_locations": attempted,
        "discovered_module_roots": results,
        "source_tree_found": bool(results),
        "overall_status": "inventory_complete_for_discovered_trees" if results and all(r["coverage_complete_for_non_symlink_tree"] for r in results) else ("inventory_incomplete_or_limited" if results else "source_tree_unavailable"),
        "interpretation_limit": "A filename or path match is an inventory lead, not evidence that a module applies to the supplied OpenSSH service. Source contents and candidate-specific checks were not reviewed by this action."
    }
    print(json.dumps(output, sort_keys=True))


if __name__ == "__main__":
    main()

