import hashlib
import json
import os
import re
from pathlib import Path

ARCHIVE = "llm_inputs/c5b26d26bbb857ed404d537b934cd9b92a72caf24be21a283e29bf7e95dee8fd.json"
KNOWN_REFS = {
    "b37a4c7c899327e20e4990dbba9e44fb9a97ab9225584df6b2b3a36c4976f404",
    "137feee21df21e512ffc41be7faaebbad36e8db809ffc824951d0da68853ad32",
    "f2cf67e5bee750afbf86edcaa8873592f62c0f38ef547a44f839b087ce404068",
}


def json_path(root, expression):
    """Resolve the simple bracketed JSON paths used in supplied source references."""
    if not isinstance(expression, str) or not expression.startswith("$"):
        raise ValueError("unsupported source_path syntax")
    current = root
    for match in re.finditer(r"\[(\"(?:\\.|[^\"])*\"|\d+)\]", expression[1:]):
        token = match.group(1)
        key = json.loads(token) if token.startswith('"') else int(token)
        current = current[key]
    return current


def content_bytes(value):
    if isinstance(value, str):
        return value.encode("utf-8")
    return json.dumps(value, ensure_ascii=False, separators=(",", ":")).encode("utf-8")


def emit_source(label, source_path, value, expected_bytes=None, reference_partial=None):
    raw = content_bytes(value)
    actual_bytes = len(raw)
    is_reference_stub = isinstance(value, dict) and "evidence_ref" in value and "source_path" in value
    exact_size = expected_bytes is None or actual_bytes == expected_bytes
    complete = not is_reference_stub and exact_size and reference_partial is not True
    print(json.dumps({
        "record_type": "source",
        "label": label,
        "source_path": source_path,
        "value_type": type(value).__name__,
        "bytes_emitted": actual_bytes,
        "expected_original_bytes": expected_bytes,
        "sha256_of_emitted_content": hashlib.sha256(raw).hexdigest(),
        "reference_marked_partial": reference_partial,
        "complete_assessment": "complete" if complete else "incomplete_or_unverified",
        "content_encoding": "raw_utf8" if isinstance(value, str) else "compact_json_utf8"
    }, ensure_ascii=False))
    if isinstance(value, str):
        print(value)
    else:
        print(json.dumps(value, ensure_ascii=False, separators=(",", ":")))
    if not complete:
        reasons = []
        if is_reference_stub:
            reasons.append("the extracted value is an evidence-reference stub, not the referenced full content")
        if not exact_size:
            reasons.append("emitted byte count differs from the recorded original byte count")
        if reference_partial is True:
            reasons.append("the reference metadata marks the source partial")
        if expected_bytes is None:
            reasons.append("no original byte count was available to verify completeness")
        print(json.dumps({"record_type": "coverage_limitation", "label": label, "reasons": reasons}, ensure_ascii=False))


def main():
    candidates = [Path(ARCHIVE), Path("/root") / ARCHIVE]
    archive_path = next((p for p in candidates if p.is_file()), None)
    if archive_path is None:
        print(json.dumps({
            "record_type": "retrieval_failure",
            "source": ARCHIVE,
            "paths_checked": [str(p) for p in candidates],
            "error": "The specifically supplied archive path was not readable at either checked location; no broader filesystem search was performed."
        }, ensure_ascii=False))
        return

    try:
        archive_raw = archive_path.read_bytes()
        archive_text = archive_raw.decode("utf-8")
        archive = json.loads(archive_text)
    except Exception as exc:
        print(json.dumps({
            "record_type": "retrieval_failure",
            "source": str(archive_path),
            "error_type": type(exc).__name__,
            "error": str(exc),
            "bytes_read": archive_path.stat().st_size if archive_path.exists() else None
        }, ensure_ascii=False))
        return

    print(json.dumps({
        "record_type": "archive_metadata",
        "supplied_archive": ARCHIVE,
        "resolved_path": str(archive_path.resolve()),
        "bytes_read": len(archive_raw),
        "sha256": hashlib.sha256(archive_raw).hexdigest(),
        "utf8_and_json_parse": "successful",
        "note": "The archive is emitted in full below. Generated artifacts (including /root/scripts) are not treated as credential evidence. No authentication is attempted."
    }, ensure_ascii=False))
    emit_source("complete_original_input_archive", str(archive_path), archive_text, len(archive_raw), False)

    refs = []
    def walk(value):
        if isinstance(value, dict):
            if value.get("evidence_ref") in KNOWN_REFS or (
                isinstance(value.get("sha256"), str)
                and value.get("sha256") in KNOWN_REFS
                and isinstance(value.get("source_path"), str)
            ):
                refs.append(value)
            for child in value.values():
                walk(child)
        elif isinstance(value, list):
            for child in value:
                walk(child)

    walk(archive)
    by_ref = {}
    for item in refs:
        ref = item.get("evidence_ref") or item.get("sha256")
        if ref in KNOWN_REFS:
            by_ref.setdefault(ref, item)

    known_paths = {
        "b37a4c7c899327e20e4990dbba9e44fb9a97ab9225584df6b2b3a36c4976f404": '$["prior_observations"]',
        "137feee21df21e512ffc41be7faaebbad36e8db809ffc824951d0da68853ad32": '$["hierarchy_context"]["parent_dependency_results"][0]["observation"]["execution_result"]["stdout"]',
        "f2cf67e5bee750afbf86edcaa8873592f62c0f38ef547a44f839b087ce404068": '$["hierarchy_context"]["parent_dependency_results"][0]["observation"]["child_observations"]',
    }
    for ref in sorted(KNOWN_REFS):
        metadata = by_ref.get(ref)
        source_path = metadata.get("source_path") if metadata else known_paths[ref]
        expected_bytes = metadata.get("original_bytes") if metadata else None
        partial = metadata.get("partial") if metadata else None
        try:
            value = json_path(archive, source_path)
            emit_source("referenced_source_" + ref, source_path, value, expected_bytes, partial)
        except Exception as exc:
            print(json.dumps({
                "record_type": "source_retrieval_failure",
                "evidence_ref": ref,
                "source_path": source_path,
                "expected_original_bytes": expected_bytes,
                "reference_partial": partial,
                "error_type": type(exc).__name__,
                "error": str(exc),
                "coverage": "The referenced source could not be obtained or interpreted from the supplied archive. Its omitted contents remain unknown."
            }, ensure_ascii=False))

    print(json.dumps({
        "record_type": "interpretation_boundary",
        "finding": "This retrieval records source contents and coverage only. It does not infer credentials from SSH authentication methods, generated scripts, or missing/truncated material. Any credential finding must be assessed from explicitly supplied evidence in the retrieved complete sources."
    }, ensure_ascii=False))


if __name__ == "__main__":
    main()
